使用RecursiveCharacterTextSplitter，对过长 Chunk 进行二次处理,实现长切短合

```python
    def get_final_section_list(self, section_list):
        #       长切
        max_length = 500
        overlap = 50
        final_section_list = []
        spliter = RecursiveCharacterTextSplitter(
            separators=["\n\n", "\n", "。", "！", "？", "；", ".", "!", "?", ";", " "],
            chunk_size=max_length,
            chunk_overlap=overlap,
        )
        for section in section_list:
            content = section.get("content")
            title = section.get("title")
            real_content = (content[len(title):] if content.startswith("#") else content)
            if len(real_content) <= max_length:
                final_section_list.append({
                    **section,
                    "part": 0
                })
                continue

            if "<table" in content:
                final_section_list.append({
                    **section,
                    "part": 0
                })
                continue

            splite_section_chunks = spliter.split_text(real_content)
            for idx, section_chunk in enumerate(splite_section_chunks, start=1):
                final_section_list.append({
                    **section,
                    "part": idx,
                    "content": title + "\n\n" + section_chunk
                })
        return final_section_list
